  buf->f_type = MSDOS_SUPER_MAGIC;
  buf->f_bsize = fs->fs_fatsecperclus * fs->fs_hwsectorsize;
  ret = fat_nfreeclusters(fs, &buf->f_bfree);
  if (ret >= 0)
    {
      buf->f_blocks = fs->fs_nclusters;
      buf->f_bavail = buf->f_bfree;
      buf->f_namelen = (8 + 1 + 3);
    }
errout_with_lock:
  nxmutex_unlock(&fs->fs_lock);
  return ret;
}
