static inline int fat_parsesfname(FAR const char **path,
                                  FAR struct fat_dirinfo_s *dirinfo,
                                  FAR char *terminator)
{
  FAR const char *node = *path;
  int endndx;
  uint8_t ch;
  int ndx = 0;
  memset(dirinfo->fd_name, ' ', DIR_MAXFNAME);
  endndx = 8;
  for (; ; )
    {
      ch = *node++;
      if ((ch == '\0' || ch == '/') && ndx != 0)
        {
          *terminator = ch;
          *path = node;
          return OK;
        }
      else if (!isgraph(ch))
        {
          goto errout;
        }
      else if (ch == '.' && endndx == 8)
        {
          ndx = 8;
          endndx = 11;
          continue;
        }
      else if (ch == '"' || (ch >= '*' && ch <= ',') ||
               ch == '.' || ch == '/' ||
              (ch >= ':' && ch <= '?') ||
              (ch >= '[' && ch <= ']') ||
              (ch == '|'))
        {
          goto errout;
        }
      else if (islower(ch))
        {
          ch = toupper(ch);
        }
      if (ndx >= endndx)
        {
          goto errout;
        }
      dirinfo->fd_name[ndx++] = ch;
    }
errout:
  return -EINVAL;
}
