  fs = inode->i_private;
  DEBUGASSERT(fs != NULL);
  if ((ff->ff_bflags & UMOUNT_FORCED) == 0)
    {
      ret = fat_sync(filep);
      for (prevff = NULL, currff = fs->fs_head;
           currff && currff != ff;
           prevff = currff, currff = currff->ff_next);
      if (currff)
        {
          if (prevff)
            {
              prevff->ff_next = ff->ff_next;
            }
          else
            {
              fs->fs_head = ff->ff_next;
            }
        }
    }
  if (ff->ff_buffer)
    {
      fat_io_free(ff->ff_buffer, fs->fs_hwsectorsize);
    }
