}
int fat_fscacheread(struct fat_mountpt_s *fs, off_t sector)
{
  int ret;
  if (fs->fs_currentsector != sector)
    {
      ret = fat_fscacheflush(fs);
      if (ret < 0)
        {
          return ret;
        }
      ret = fat_hwread(fs, fs->fs_buffer, sector, 1);
      if (ret < 0)
        {
          return ret;
        }
      fs->fs_currentsector = sector;
    }
  return OK;
}
